{
  "status": "answered",
  "claims": [
    {
      "text": "Феодосий III родился в неизвестное время и в неизвестном месте; по одной из версий, он был сыном императора Тиберия III.",
      "evidence_ids": [3]
    },
    {
      "text": "В мае 715 года Феодосий был назначен сборщиком податей в Мёзии, где восстал против Анастасия II и был провозглашен императором.",
      "evidence_ids": [3]
    },
    {
      "text": "Феодосий сначала отказывался от власти и пытался бежать, но был принужден к принятию власти и отправлен в поход на Константинополь.",
      "evidence_ids": [3]
    },
    {
      "text": "В ноябре 715 года (через шесть месяцев после начала осады) Феодосий и его войско, благодаря измене, проникли в Константинополь.",
      "evidence_ids": [3]
    }
  ]
}
